  "electronics-engineer": { about: "Designs electronic components and systems such as circuits and devices. Uses simulation software and tests prototypes.", day: ["Reviews the design specs and updates the circuit designs.","Runs the simulations and tests the circuit prototypes carefully.","Works with the teams on production and troubleshooting."] },
  "electronics-engineers-except-computer": { about: "Designs and tests electronic systems other than computers. Develops circuits, components, and devices.", day: ["Reviews the requirements and refines the circuit designs.","Builds and tests the electronic prototypes in the lab daily.","Troubleshoots the issues and documents the design changes."] },
  "elementary-school-teacher": { about: "Teaches core subjects to children in elementary schools. Plans lessons, guides activities, and tracks student progress.", day: ["Prepares the lessons and reviews the day's full schedule.","Teaches reading, math, and other subjects to the class.","Grades the student work and meets with parents or staff."] },
