  "eligibility-interviewers-government-programs": { about: "Reviews applications for government assistance programs. Interviews applicants and verifies eligibility.", day: ["Reviews applications and requests supporting documents.","Interviews the applicants and verifies their information.","Updates case files and notifies applicants of decisions."] },
  "embalmer": { about: "Prepares bodies for funerals using preservation techniques. Cleans, treats, and restores remains for viewing.", day: ["Reviews the service arrangement and the family records.","Cleans and preserves the body carefully for the viewing.","Prepares the final presentation and documents the work."] },
