  "emergency-medical-technician": { about: "Provides emergency medical care at accident scenes and during transport. Assesses patients, gives first aid, and responds to calls.", day: ["Checks the ambulance and restocks the medical supplies.","Responds to the emergency calls and assesses each patient.","Provides care during the transport and completes reports."] },
  "emergency-medicine-physicians": { about: "Treats patients with urgent and life-threatening conditions in emergency rooms. Assesses quickly, stabilizes patients, and orders care.", day: ["Reviews the incoming patients and prioritizes by urgency.","Examines and stabilizes patients in the emergency room.","Orders tests and treatments and updates the full care team."] },
  "endoscopy-technicians": { about: "Assists with endoscopic procedures that look inside the body. Prepares instruments, supports the doctor, and cleans equipment.", day: ["Prepares the procedure room and the endoscopy instruments.","Assists during the procedures and monitors the patient.","Cleans and disinfects the equipment thoroughly after use."] },
  "energy-auditor": { about: "Inspects buildings to find ways to save energy. Measures energy use, checks systems, and recommends improvements.", day: ["Reviews the building plan and the past energy use records.","Tests the insulation, lighting, and heating systems closely.","Writes the recommendations and reports on energy savings."] },
  "energy-engineer": { about: "Designs systems that produce and use energy efficiently. Works on power generation, heating, and renewable projects.", day: ["Reviews the project specs and energy performance targets.","Designs the energy systems and runs the efficiency models.","Coordinates with the sites and reviews system performance."] },
  "energy-engineers-except-wind-and-solar": { about: "Designs energy systems other than wind and solar projects. Works on power plants, grids, and efficiency.", day: ["Reviews the designs and the energy system requirements.","Models the system performance and the overall efficiency.","Coordinates with the plant or grid teams on any changes."] },
  "engine-and-other-machine-assemblers": { about: "Assembles engines and heavy machinery from parts. Reads diagrams, fits components, and checks assembly.", day: ["Reads the assembly plan and gathers all the engine parts.","Fits and bolts the components into the engine block securely.","Checks the completed assembly and prepares it for testing."] },
  "engineer": { about: "Designs and tests products, structures, and systems across many fields. Solves technical problems and turns ideas into working solutions.", day: ["Reviews the project requirements and the existing designs.","Develops and tests the prototypes or the system designs.","Works with the teams on builds and fixes the issues found."] },
  "engineering-manager": { about: "Leads teams of engineers and directs technical projects. Plans work, reviews designs, and coordinates resources.", day: ["Reviews project status and sets priorities for the team.","Guides the engineers on designs and technical decisions.","Coordinates schedules, resources, and stakeholder updates."] },
  "engineering-teachers-postsecondary": { about: "Teaches engineering courses and labs covering design and math. Prepares lessons, grades assignments, and guides students.", day: ["Prepares the lectures and lab exercises for the day ahead.","Teaches the engineering theory and runs the lab sessions.","Grades the assignments and meets with students on questions."] },
  "english-language-and-literature-teachers-postsecondary": { about: "Teaches literature, writing, and language courses to postsecondary students. Plans lessons, grades essays, and guides class discussion and research.", day: ["Plans lectures, assignments, and readings for the week.","Leads seminar discussions about texts and student writing.","Grades essays, offers detailed feedback, and holds office hours."] },
  "english-teacher": { about: "Teaches reading, writing, and literature to teenage students. Plans lessons, grades assignments, and supports writing skills in class.", day: ["Reviews the lesson plan and prepares reading materials.","Guides the class through analysis of stories and essays.","Grades papers, gives feedback, and tracks student progress."] },
  "entertainment-and-recreation-managers-except-gambling": { about: "Oversees venues such as theaters, parks, and clubs. Hires staff, manages schedules and budgets, and coordinates shows and events.", day: ["Reviews the schedule, bookings, and staffing for the day.","Checks the venue and walks the team through safety and setup.","Handles walk-ins, resolves issues, and reviews ticket counts."] },
