  "environmental-compliance-inspectors": { about: "Inspects facilities to verify they follow environmental regulations and permits. Collects samples, reviews records, and writes reports on findings.", day: ["Reads the inspection list and gathers forms and sampling gear.","Visits sites to check equipment, records, and waste handling.","Writes findings and issues notices or follow-up actions."] },
  "environmental-economists": { about: "Studies how environmental policies and natural resources affect economies. Analyzes data, estimates costs and benefits, and advises on policy options.", day: ["Pulls data sets and reviews recent policy and market news.","Builds cost and benefit models for proposed rules and plans.","Writes summaries and presents findings to decision makers."] },
