  "environmental-science-and-protection-technicians-including-health": { about: "Performs lab and field work to monitor pollution and protect public health. Collects samples, runs tests, and reports on hazards.", day: ["Gathers sampling gear and reviews the day's monitoring plan.","Collects water, soil, or air samples at the assigned sites.","Runs lab tests, logs results, and flags any unusual readings."] },
  "environmental-science-teachers-postsecondary": { about: "Teaches environmental science topics to postsecondary students. Plans lectures and labs, grades work, and supervises student research projects.", day: ["Prepares lectures, lab setups, and materials for the class.","Leads class sessions and runs lab experiments with students.","Grades assignments and meets students to discuss their work."] },
  "environmental-scientist": { about: "Studies the environment and how human activity affects it. Collects samples, analyzes data, and advises on protecting land, water, and wildlife.", day: ["Reviews the study plan and checks field gear and supplies.","Collects samples and records conditions at each field site.","Analyzes data, writes reports, and shares results with teams."] },
  "environmental-scientists-and-specialists-including-health": { about: "Monitors pollution and environmental conditions to protect ecosystems and human health. Tests samples and reviews data for reports and guidance.", day: ["Checks monitoring schedules and reviews recent sample results.","Collects samples and prepares them for laboratory analysis.","Writes findings and advises teams on safety and compliance."] },
