  "equal-opportunity-representatives-and-officers": { about: "Helps organizations apply fair treatment rules and respond to concerns. Reviews cases, advises staff, and tracks how rules are followed.", day: ["Logs new cases and checks each file for the required steps.","Meets with parties to hear concerns and gather key details.","Prepares reports and tracks follow-up on every open case."] },
  "equity-research-analyst": { about: "Studies companies to assess financial performance and prospects. Reads statements, builds models, and writes investment reports.", day: ["Reviews earnings reports, filings, and market news overnight.","Builds valuation models and updates forecast spreadsheets.","Writes research notes and briefs the portfolio team on findings."] },
  "escrow-officer": { about: "Coordinates the transfer of property documents and funds during a sale. Reviews contracts, clears conditions, and runs the closing meeting.", day: ["Reviews new files and confirms all closing documents are ready.","Checks closing funds and verifies conditions from both parties.","Runs the closing meeting and sends out the signed papers."] },
  "esl-teacher": { about: "Teaches English to learners who speak other languages. Plans lessons on speaking, reading, and writing, and adapts activities to different levels.", day: ["Prepares lesson materials and plans activities for the class.","Runs speaking, listening, and reading practice with students.","Grades assignments and gives each student feedback on progress."] },
