  "event-planner": { about: "Plans weddings, conferences, and parties from start to finish. Works with clients on themes and budgets, then coordinates the details.", day: ["Reviews client notes and the full event checklist for the week.","Confirms bookings with vendors and updates the run sheet.","Tours the site, reviews setup, and solves any last issues."] },
