  "exercise-trainers-and-group-fitness-instructors": { about: "Leads exercise sessions for individuals or groups in gyms and studios. Demonstrates moves, corrects form, and builds training plans.", day: ["Checks the class schedule and sets up equipment and space.","Leads the workout and gives form cues to the participants.","Closes the session, answers questions, and cleans the studio."] },
