  "insurance-underwriter": { about: "Assesses risk to decide whether to accept insurance applications. Reviews information and sets policy terms.", day: ["Reviews the applications and the risk assessment data first.","Analyzes the risks and sets the policy terms and rates.","Documents the decisions and answers the agent questions."] },
