  "it-project-manager": { about: "Leads technology projects from planning to delivery. Manages tasks, timelines, the team, and budgets.", day: ["Reviews the project plans, the scope, and the timelines.","Tracks the project tasks and manages the delivery team.","Reports the progress and resolves the issues as they arise."] },
