  "judges-magistrate-judges-and-magistrates": { about: "Hears cases in court, rules on motions, and manages proceedings. Issues decisions, sets conditions, and oversees trials and hearings.", day: ["Reads briefs and motions filed for the morning's cases.","Presides over hearings and rules on requests and objections.","Drafts orders and hands down decisions to both parties."] },
  "judicial-law-clerks": { about: "Supports judges by researching case law and reviewing legal documents. Drafts opinions, memoranda, and court orders for review.", day: ["Reviews briefs and case files assigned for the court term.","Researches precedents and summarizes findings in memoranda.","Drafts opinions and checks citations before submission."] },
